const CALLS = 100;
const INTERP = 50;
const RECOMPILE = 1000;
const noOpt = CALLS * INTERP;
const deoptLoop = CALLS * (INTERP + RECOMPILE);
const cheaper = noOpt < deoptLoop ? 'no-opt' : 'deopt-loop';
console.log('noOpt=' + noOpt + ' deoptLoop=' + deoptLoop + ' cheaper=' + cheaper);
